import './chrome-next.css'
import './chrome-next-mobile.css'
import './school-rooms.css'
import './features/editorial.css'
import './mobile-inputs.css'
import '@fontsource/anton/latin-400.css'
import '@fontsource/anton/latin-ext-400.css'
import {mount as mountFeature,cleanup as cleanupFeature,onCleanup} from './features/runtime.js'
import {createClient} from '@supabase/supabase-js'
import {createPreviewData} from './chrome-next-data.js'

const url=import.meta.env.VITE_SUPABASE_URL,key=import.meta.env.VITE_SUPABASE_ANON_KEY
const client=url&&key?createClient(url,key):null
// Keep guest room sessions separate from the site's Clerk/Supabase account session.
const roomClient=url&&key?createClient(url,key,{auth:{storageKey:'nitra-school-rooms-auth',autoRefreshToken:true,persistSession:true,detectSessionInUrl:false}}):null
const api=createPreviewData(client),root=document.querySelector('#chrome-app'),sheet=document.querySelector('#sheet')
const routes={chat:'Chaty',rooms:'Roomky',events:'Eventy','unreleased-tells':'Tells',account:'Účet'}
const paths={tells:'M3 5h18v12H9l-5 4v-4H3ZM7 9h10M7 13h6',home:'M3 11 12 3l9 8M5 10v11h5v-7h4v7h5V10',chat:'M8 4h8a5 5 0 0 1 5 5v6a5 5 0 0 1-5 5H8a5 5 0 0 1-5-5V9a5 5 0 0 1 5-5Z',events:'m12 2 10 10-10 10L2 12Z',people:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10',search:'M10.5 3a7.5 7.5 0 1 0 0 15 7.5 7.5 0 0 0 0-15M16 16l5 5',arrow:'M6 18 18 6M6 6h12v12',close:'m6 6 12 12M6 18 18-12',user:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8M4 21v-2a8 8 0 0 1 16 0v2Z',bell:'M5 17h14l-2-4V9a5 5 0 0 0-10 0v4ZM10 21h4',lock:'M7 10V7a5 5 0 0 1 10 0v3M5 10h14v11H5ZM12 14v3',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7M3 21 21 3',heart:'M12 21 3 12C-2 5 7 0 12 7 17 0 26 5 21 12Z',chevron:'m9 5 7 7-7 7',logout:'M9 3H3v18h6M9 12h12m-5-5 5 5-5 5',trash:'M4 7h16M10 11v6M14 11v6M6 7l1 14h10l1-14M9 7V4h6v3'}
const icon=(name)=>`<svg class="${name}-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.arrow}"/></svg>`
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))
const ornament=()=>''
let route='',generation=0,cache={},filter='Všetky',register=false,returnFocus=null,toastTimer,eventRoomChannel=null
const defaultSchoolRooms=[
 {id:1,label:'Animus'},{id:2,label:'Obchodka'},{id:3,label:'Cabajská · stavebná'},
 {id:4,label:'Cabajská · potravinárska'},{id:5,label:'Cintorínska'},{id:6,label:'Červeňova'},
 {id:7,label:'Veterina'},{id:8,label:'GCM'},{id:9,label:'Zdravotka'},
 {id:10,label:'Fraňa Kráľa'},{id:11,label:'Golianka'},{id:12,label:'Konzervatórium'},
 {id:13,label:'Gastro'},{id:14,label:'Nábrežie'},{id:15,label:'Polytechnika'},
 {id:16,label:'Párovská'},{id:17,label:'Piaristi'},{id:18,label:'Samova'},
 {id:19,label:'Slančíkova · gym'},{id:20,label:'Hotelovka'},
 {id:21,label:'Slančíkova · potravinárska'},{id:22,label:'Športová'}
]
let schoolRooms=[...defaultSchoolRooms],schoolRoomsLoaded=false,schoolRoomsAttempted=false,schoolRoomsLoading=false,schoolRoomsError='',activeSchoolRoomId=null,schoolRoomChannel=null,schoolRoomGeneration=0
const toast=message=>{const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),5000)}
const data=name=>cache[name]?.data||[]
const account=()=>cache.account?.status==='ready'?cache.account.data:null
const navLink=(id,label)=>`<a href="${id==='random'?'/random':id==='chat'?'/chat':['polls','account','unreleased-tells'].includes(id)?'/'+id:'/space#'+id}" ${route===id?'aria-current="page"':''}>${label}</a>`
function shell(){root.innerHTML=`<header><a class="logo" href="/chat" aria-label="Nitra Space — chat"><img src="/nitra-space-logo-optimized.webp" alt="Nitra Space"></a><nav class="desktop-nav" aria-label="Hlavná navigácia">${Object.entries(routes).map(([id,label])=>navLink(id,label)).join('')}</nav><div class="header-actions"><button class="circle" data-action="search" aria-label="Vyhľadať">${icon('search')}</button><a class="circle" href="/account" aria-label="Môj účet">${icon('user')}</a></div></header><main id="main"></main><nav class="bottom-nav" aria-label="Spodná navigácia">${[['chat','chat'],['rooms','user'],['events','events'],['unreleased-tells','tells'],['account','user']].map(([id,i])=>navLink(id,icon(i)+routes[id])).join('')}</nav>`}
const hero=(name,title,sub,extra='')=>`<section class="hero ${name}">${ornament()}<div class="eyebrow">/ ${routes[name]?.toUpperCase()||name}</div><h1>${title.split('|').map(t=>`<span>${t}</span>`).join('')}</h1>${extra}${sub?`<p>${sub}</p>`:''}</section>`
const button=(href,label)=>`<a class="primary" href="${href}">${label}${icon('arrow')}</a>`
const chips=(items)=>`<div class="chips" aria-label="Filtrovanie">${items.map(t=>`<button data-filter="${esc(t)}" aria-pressed="${filter===t}">${esc(t)}</button>`).join('')}</div>`
function status(name,empty){const r=cache[name];if(!r)return '<div class="empty" role="status">Načítavam…</div>';if(r.status==='error')return `<div class="empty"><h2>Nepodarilo sa pripojiť.</h2><p>${esc(r.error)}</p><button data-action="retry">Skúsiť znova</button></div>`;if(!r.data?.length)return `<div class="empty">${empty}</div>`;return ''}
function home(){const shortcut=[['tellonym','Tellonym','https://tellonym.me/nitraspace'],['polls','Ankety','#polls'],['people','Matching','#people'],['account','Účet','#account']];return `<div class="page home"><section class="home-hero">${ornament()}<div class="coordinates">NITRA<br>SLOVAKIA<br>48.3067° N<br>18.0828° E</div><h1 class="home-title"><img src="/nitra-space-logo-optimized.webp" alt="Nitra Space"></h1><p class="home-tagline">ONE CITY.<br>ONE SPACE.</p></section><div class="shortcuts">${shortcut.map(([id,label,href],i)=>`<a class="shortcut" href="${href}" ${id==='tellonym'?'target="_blank" rel="noopener noreferrer"':''}><small>0${i+1}</small>${ornament()}<strong>${label}</strong></a>`).join('')}</div><div class="stats"><div><b>${cache.events?.status==='ready'?data('events').length:'—'}</b><small>Eventov</small></div><div><b>${cache.people?.status==='ready'?data('people').length:'—'}</b><small>Profilov vo výbere</small></div><div><b>${cache.polls?.status==='ready'?data('polls').length:'—'}</b><small>Ankiet</small></div></div>${button('#chat','Objav Nitra Space')}</div>`}
function chat(){return `<div class="page chat chat-full anonymous-chat-page"><div class="anonymous-chat-shell"><iframe class="anonymous-chat-frame" src="/chat.html?embed=1&rev=mobile-safe-area-20261115&match=gender" title="Anonymný chat Nitra Space"></iframe></div></div>`}
function schoolRoomsPage(){
 const room=schoolRooms.find(item=>String(item.id)===String(activeSchoolRoomId))
 if(room)return `<div class="page school-rooms-page school-room-chat-page"><button class="school-rooms-back" type="button" data-school-rooms-back>${icon('chevron')} Všetky roomky</button><section class="school-room-heading"><span class="section-heading">NITRA SPACE / ROOMKA</span><h1>${esc(room.label)}</h1><p>Anonymne · bez registrácie · začni písať</p></section><section class="school-room-chat" data-school-room-panel="${esc(room.id)}"><div class="school-room-live"><span><i></i> <b data-school-room-state>Čakám na ľudí…</b></span><span class="school-room-online"><i></i><b data-school-room-online>1</b> ONLINE</span></div><div class="school-room-messages" data-school-room-messages aria-live="polite"><p class="school-room-empty">Pripájam roomku…</p></div><form class="school-room-form" data-school-room-form><button type="button" class="school-room-next" data-school-room-next>ĎALŠÍ</button><input name="body" maxlength="500" autocomplete="off" placeholder="Napíš správu…" required><button class="school-room-send" type="submit">ODOSLAŤ</button><button type="button" class="school-room-leave" data-school-rooms-back>ODÍSŤ</button></form></section></div>`
 const list=schoolRooms.map(item=>`<button class="school-room-card" type="button" data-school-room="${esc(item.id)}"><span class="school-room-number">${String(item.id).padStart(2,'0')}</span><span class="school-room-card-copy"><strong>${esc(item.label)}</strong><small>Verejná · anonymná roomka</small></span>${icon('arrow')}</button>`).join('')
 return `<div class="page school-rooms-page"><section class="school-rooms-heading"><span class="section-heading">NITRA SPACE / KOMUNITA</span><h1>ŠKOLSKÉ<br>ROOMKY</h1><p>Stredné školy a gymnáziá v Nitre. Vyber si svoju partiu a zapoj sa do chatu.</p><small>Skrátené prezývky, bez oficiálnych názvov a log. V chate nezdieľaj celé meno ani súkromné kontakty.</small><span class="school-rooms-count">22 ROOMIEK · NITRA</span></section><div class="school-rooms-status" data-school-rooms-status aria-live="polite">${schoolRoomsLoading?'Pripájam sa…':schoolRoomsError?`${esc(schoolRoomsError)} <button type="button" data-school-rooms-retry>Skúsiť znova</button>`:''}</div><div class="school-room-list" data-school-rooms-list>${list}</div></div>`
}
function pollCard(p,i){return `<article class="card poll-card"><div class="card-top"><span>${String(i+1).padStart(2,'0')}</span><span>${p.closesAt?'Do '+date(p.closesAt):'Anketa'}</span></div><h2>${esc(p.question)}</h2>${p.options.map(o=>`<button class="option ${p.resultsVisible?'':'voteable'}" data-poll="${esc(p.id)}" data-option="${esc(o.id)}" ${p.resultsVisible?'disabled':''}><span class="option-label"><span>${esc(o.label)}</span><span>${p.resultsVisible?`${o.percent??0}%`:icon('arrow')}</span></span>${p.resultsVisible?`<span class="track"><i style="width:${Math.max(0,Math.min(100,Number(o.percent)||0))}%"></i></span>`:''}</button>`).join('')}<p class="muted">${p.resultsVisible?`${p.totalVotes??0} hlasov · Tvoj hlas je uložený.`:'Hlasuj a pozri si výsledky.'}</p></article>`}
function polls(){const all=data('polls'),items=filter==='Všetky'?all:all.filter(p=>p.kind===filter);return `<div class="page polls">${hero('polls','HLASUJ.','', '<h2>TVOR NITRU.</h2>')}${chips(['Všetky',...new Set(all.map(p=>p.kind).filter(Boolean))])}<div class="cards">${status('polls','Momentálne nie je zverejnená žiadna anketa.')||items.map(pollCard).join('')||'<p class="empty">V tejto kategórii zatiaľ nič nie je.</p>'}</div></div>`}
const date=s=>{const d=new Date(s);return Number.isNaN(d.getTime())?esc(s):d.toLocaleDateString('sk-SK',{day:'numeric',month:'numeric',year:'numeric'})}
function category(e){const t=`${e.title} ${e.performer}`.toLowerCase();return /festival/.test(t)?'Festivaly':/koncert/.test(t)?'Koncerty':'Párty'}
function events(){const items=data('events');return `<div class="page events">${hero('events','KAM|DNES?','<span style="color:var(--blue)">NITRA ŽIJE.</span>')}${cache.isAdmin?.data===true?`<a class="outline events-admin-link" href="/social.html?admin=1#events">${icon('lock')} Spravovať eventy ${icon('arrow')}</a>`:''}<div class="cards">${status('events','Aktuálne tu nie sú žiadne eventy.')||items.map(e=>`<article class="card event-card"><div class="event-card-media">${e.image?`<img src="${esc(e.image)}" alt="Plagát: ${esc(e.title)}" loading="lazy">`:'<div class="event-card-no-image">Plagát sa pripravuje</div>'}<button class="circle" data-event="${esc(e.id)}" aria-label="Detail ${esc(e.title)}">${icon('arrow')}</button></div><div class="event-card-body"><h2>${esc(e.title)}</h2><p class="event-event-meta">${date(e.date)} <span>·</span> ${esc(e.place)}</p><p class="event-performer">${esc(e.performer||'Interpreti budú oznámení')}</p><p class="event-organizer">${esc(e.organizer||'Nitra')}</p>${e.instagramGroupUrl?`<div class="event-card-actions"><a class="event-instagram-card-link" href="${esc(e.instagramGroupUrl)}" target="_blank" rel="noopener noreferrer">Instagram skupina ${icon('arrow')}</a></div>`:''}</div></article>`).join('')||'<p class="empty">Aktuálne tu nie sú žiadne eventy.</p>'}</div></div>`}
const avatar=p=>p.avatarUrl?`<img class="avatar" src="${esc(p.avatarUrl)}" alt="${esc(p.name)}">`:`<span class="avatar">${esc((p.name||'N').slice(0,1))}</span>`
function people(){const items=data('people').filter(p=>filter==='Všetci'||(p.interests||[]).includes(filter));return `<div class="page people">${hero('people','SPOZNAJ|ĽUDÍ|Z NITRY.','SKUTOČNÍ ĽUDIA.<br>ŽIADNE MASKY.')}${chips(['Všetci',...new Set(data('people').flatMap(p=>p.interests||[]))].slice(0,10))}<div class="cards">${status('people','Profily zatiaľ nie sú dostupné. Prihlás sa a nastav svoj matching profil.')||items.map(p=>`<article class="card person-card">${p.photoUrl||p.avatarUrl?`<img src="${esc(p.photoUrl||p.avatarUrl)}" alt="${esc(p.name)}" loading="lazy">`:`<div class="avatar-placeholder">${esc((p.name||'N').slice(0,1))}</div>`}<div class="person-top"><span>${p.verified?'OVERENÝ PROFIL':'NITRA SPACE'}</span><button class="circle" data-profile="${esc(p.username)}" aria-label="Otvoriť profil ${esc(p.name)}">${icon('arrow')}</button></div><div><h2>${esc(p.name)}${p.age?`, ${esc(p.age)}`:''}</h2><div class="tags">${(p.interests||[]).slice(0,3).map(t=>`<span>${esc(t)}</span>`).join('')}</div><button class="circle like" data-match="${esc(p.id)}" aria-label="Záujem o ${esc(p.name)}">${icon('heart')}</button></div></article>`).join('')||'<p class="empty">Žiadny profil s týmto záujmom.</p>'}</div><a class="outline" style="margin-top:18px" href="#account">Nastaviť môj profil${icon('arrow')}</a></div>`}
function auth(){return `<form class="auth auth-window" data-form="auth"><div class="auth-window-bar"><span>NITRA SPACE / ÚČET</span><span class="auth-window-controls" aria-hidden="true"><i>−</i><i>□</i><i>×</i></span></div><div class="auth-window-content"><div class="auth-brand"><img src="/nitra-space-logo-optimized.webp" alt=""><span>BEZPEČNÝ PRÍSTUP</span></div><div class="auth-heading"><span>${register?'REGISTRÁCIA':'PRIHLÁSENIE'}</span><h2>${register?'Vytvor si účet':'Vitaj späť'}</h2><p>${register?'Vyplň údaje, nastav heslo a potvrď e-mailový kód.':'Prihlás sa e-mailom a heslom.'}</p></div>${register?'<label>Používateľské meno<input name="username" minlength="4" maxlength="24" pattern="(?=.*[A-Za-z])[A-Za-z0-9_]{4,24}" required autocomplete="username" autocapitalize="none" spellcheck="false"><small>4–24 znakov, aspoň jedno písmeno.</small></label><label>Dátum narodenia <small>Účet je dostupný od 16 rokov.</small><input type="date" name="birthDate" required autocomplete="bday"></label>':''}<label>E-mail<input type="email" name="email" required autocomplete="email" placeholder="ty@email.sk"></label><label>Heslo<input type="password" name="password" required minlength="8" autocomplete="${register?'new-password':'current-password'}" placeholder="Aspoň 8 znakov"></label><p class="form-message" role="alert" aria-live="polite"></p><button type="submit" class="primary">${register?'Vytvoriť účet':'Prihlásiť sa'}${icon('arrow')}</button><button type="button" class="small-action" data-action="auth-toggle">${register?'Už mám účet':'Nemáš účet? Zaregistruj sa'}</button></div></form>`}
function showAuthCode(form,email){form.dataset.form='auth-code';form.innerHTML=`<div class="auth-window-bar"><span>NITRA SPACE / OVERENIE</span><span class="auth-window-controls" aria-hidden="true"><i>−</i><i>□</i><i>×</i></span></div><div class="auth-window-content"><div class="auth-brand"><img src="/nitra-space-logo-optimized.webp" alt=""><span>POSLEDNÝ KROK</span></div><div class="auth-heading"><h2>Skontroluj e-mail.</h2><p>Zadáš kód, ktorý sme poslali na <strong>${esc(email)}</strong>, a účet je hotový.</p></div><label>Overovací kód<input name="code" inputmode="numeric" autocomplete="one-time-code" required minlength="4" maxlength="12" placeholder="000000" autofocus></label><p class="form-message" role="alert" aria-live="polite"></p><button type="submit" class="primary">Potvrdiť kód${icon('arrow')}</button><button type="button" class="small-action" data-action="auth-resend-code">Poslať nový kód</button></div>`;form.querySelector('[name="code"]')?.focus()}
function accountPage(){const p=account(),showingAuth=!p&&cache.account?.status!=='error';return `<div class="page account ${showingAuth?'account-signin':''}">${showingAuth?'':hero('account','TVOJ|PRIESTOR.','VŠETKO POD KONTROLOU.')}<div class="account-content">${p?`<div class="identity">${avatar(p)}<div><strong>${esc(p.name)}</strong><p>@${esc(p.username)}</p></div></div><button class="outline" data-action="edit">Upraviť profil${icon('arrow')}</button><div class="settings">${[['edit','user','Profil'],['privacy','lock','Súkromie'],['security','lock','Bezpečnosť'],['signout','logout','Odhlásiť sa']].map(([a,i,label])=>`<button data-action="${a}">${icon(i)}${label}<span class="chevron">${icon('chevron')}</span></button>`).join('')}<a href="/account">${icon('user')}Rozšírené nastavenia a fotky<span class="chevron">${icon('arrow')}</span></a></div>`:cache.account?.status==='error'?`<div class="empty">${esc(cache.account.error)}<button data-action="retry">Skúsiť znova</button></div>`:auth()}</div></div>`}
function eventRoomPage(){const id=location.pathname.match(/^\/events\/([^/]+)\/room\/?$/)?.[1];const e=data('events').find(item=>String(item.id)===id);if(cache.events?.status!=='ready')return `<div class="page event-room-page"><p class="muted">Načítavam chat…</p></div>`;if(!e)return `<div class="page event-room-page"><h1>Event sa nenašiel.</h1><a class="outline" href="/space#events">Späť na eventy</a></div>`;if(e.roomEnabled===false)return `<div class="page event-room-page"><a class="outline" href="/space#events">Späť na eventy</a><div class="event-room-gate"><h1>${esc(e.title)}</h1><p>Organizátor vypol chat pre tento event.</p></div></div>`;const p=account();if(!cache.account)return `<div class="page event-room-page"><p class="muted">Overujem prihlásenie…</p></div>`;if(!p)return `<div class="page event-room-page"><a class="outline" href="/space#events">Späť na eventy</a><div class="event-room-gate"><span class="section-heading">${date(e.date)} · ${esc(e.place)}</span><h1>${esc(e.title)}</h1><p>Chat eventu je určená pre prihlásených návštevníkov. Prihlás sa, aby si sa mohol/mohla pridať.</p><a class="primary" href="/account">Prihlásiť sa ${icon('arrow')}</a></div></div>`;return `<div class="page event-room-page"><div class="event-room-page-head"><a class="outline" href="/space#events">${icon('chevron')} Eventy</a><div><span class="section-heading">${date(e.date)} · ${esc(e.place)}</span><h1>${esc(e.title)}</h1><p>${esc(e.performer||'')} · Chat: Chat eventu</p></div></div><section class="event-room-panel" data-event-room-page="${esc(e.id)}"><div class="event-room-page-status" data-event-room-status><p class="muted">Overujem prístup…</p></div><div class="event-room-messages" data-event-room-messages aria-live="polite" hidden></div><form class="event-room-form" data-event-room-form hidden><input name="body" maxlength="500" autocomplete="off" placeholder="Napíš do chatu pred eventom…" required><button class="primary" type="submit">Poslať ${icon('arrow')}</button></form></section></div>`}
function render(){const main=document.querySelector('#main');main.classList.toggle('is-anonymous-chat',route==='chat');document.body.classList.toggle('anonymous-chat-open',route==='chat');root.classList.toggle('account-auth-open',route==='account'&&!account()&&cache.account?.status!=='error');main.innerHTML=({board:home,chat,rooms:schoolRoomsPage,polls,events,people,account:accountPage,'event-room':eventRoomPage}[route]||home)();if(route==='rooms')mountSchoolRooms();if(route==='event-room')mountEventRoomPage()}
async function showSiteAnnouncement(){if(!client)return;try{const {data,error}=await client.rpc('get_site_announcement');if(error||!data?.active||!data.title&&!data.message)return;let image='';if(data.event_id){const event=await client.from('nitra_events').select('image_data').eq('id',data.event_id).maybeSingle();if(!event.error)image=event.data?.image_data||''}const dialog=document.createElement('dialog');dialog.className='site-announcement';dialog.setAttribute('aria-label','Upozornenie Nitra Space. Kliknutím otvoríš Eventy, potiahnutím nahor zavrieš.');dialog.setAttribute('aria-live','polite');dialog.tabIndex=0;dialog.style.zIndex='10000';dialog.innerHTML=`${image?`<img class="announcement-event-image" src="${esc(image)}" alt="Fotka eventu">`:'<span class="announcement-app-icon">N</span>'}<div class="announcement-copy"><div class="announcement-meta"><strong>NITRA SPACE</strong><time>TERAZ</time></div><h2>${esc(data.title||'Pozor, blíži sa event')}</h2><p>${esc(data.message||'')}</p></div>`;document.body.append(dialog);let swipeStart=null,autoDismiss,suppressClickUntil=0,dismissing=false;const close=()=>{if(dialog.open)dialog.close();dialog.remove()};const dismissUp=(afterClose)=>{if(!dialog.isConnected||dismissing)return;dismissing=true;window.clearTimeout(autoDismiss);dialog.style.transition='transform .42s cubic-bezier(.4,0,1,1),opacity .36s ease-out';dialog.style.transform='translate3d(0,-150%,0)';dialog.style.opacity='0';setTimeout(()=>{close();afterClose?.()},460)};const snapBack=()=>{dialog.style.transition='transform .28s cubic-bezier(.2,.8,.2,1),opacity .22s ease';dialog.style.transform='translate3d(0,0,0)';dialog.style.opacity='1';setTimeout(()=>{dialog.style.transition='';dialog.style.transform='';dialog.style.opacity=''},300)};dialog.addEventListener('pointerdown',event=>{if(event.pointerType==='mouse'||!event.isPrimary)return;dialog.style.animation='none';dialog.style.transform='';swipeStart={id:event.pointerId,x:event.clientX,y:event.clientY,time:performance.now()};dialog.style.transition='none';try{dialog.setPointerCapture(event.pointerId)}catch{}},{passive:true});dialog.addEventListener('pointermove',event=>{if(!swipeStart||event.pointerId!==swipeStart.id)return;const dy=Math.min(0,event.clientY-swipeStart.y),distance=Math.abs(dy);dialog.style.transform=`translate3d(0,${dy}px,0)`;dialog.style.opacity=String(Math.max(.42,1-distance/Math.max(dialog.offsetHeight*1.8,1)))},{passive:true});dialog.addEventListener('pointerup',event=>{if(!swipeStart||event.pointerId!==swipeStart.id)return;const dx=event.clientX-swipeStart.x,dy=event.clientY-swipeStart.y,elapsed=Math.max(performance.now()-swipeStart.time,1),velocity=dy/elapsed;swipeStart=null;if(dy<-48&&Math.abs(dy)>Math.abs(dx)*1.15||velocity<-.55&&Math.abs(dy)>18){suppressClickUntil=Date.now()+500;dismissUp()}else snapBack()},{passive:true});dialog.addEventListener('pointercancel',()=>{if(swipeStart){swipeStart=null;snapBack()}},{passive:true});dialog.addEventListener('click',event=>{if(Date.now()<suppressClickUntil){event.preventDefault();return}dismissUp(()=>{if(location.hash!=='#events')location.hash='#events'})});dialog.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();dismissUp(()=>{if(location.hash!=='#events')location.hash='#events'})}});dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.addEventListener('animationend',event=>{if(event.animationName!=='iphone-notice-drop')return;dialog.style.animation='none';dialog.style.transform=''}, {once:true});setTimeout(()=>{if(dialog.isConnected&&dialog.style.animation!=='none'){dialog.style.animation='none';dialog.style.transform=''}},700);dialog.show();autoDismiss=setTimeout(dismissUp,20000)}catch(error){console.warn('Announcement load failed:',error.message)}}
async function mountGlobalChat(){
 const box=document.querySelector('[data-global-chat]'),messages=document.querySelector('[data-global-messages]'),form=document.querySelector('[data-global-form]');
 if(!box||!messages||!form)return;
 if(!client){messages.innerHTML='<p class="muted">Chat momentálne nie je dostupný.</p>';form.remove();return}
 const session=await client.auth.getSession(),user=session.data.session?.user;
 if(!user){messages.innerHTML='<p class="muted">Pre vstup do globálneho chatu sa prihlás.</p><a class="primary" href="/account">Prihlásiť sa '+icon('arrow')+'</a>';form.remove();return}
 let rows=[],profileNames=new Map(),profileAvatars=new Map(),channel,canModerate=false;
 const adminCheck=await client.rpc('is_admin');canModerate=adminCheck.data===true;
 const paint=()=>{messages.innerHTML=rows.map(row=>{const name=profileNames.get(row.user_id)||'Nitra Space',photo=profileAvatars.get(row.user_id);return `<article class="global-chat-message ${row.user_id===user.id?'mine':''}"><span class="global-chat-avatar">${photo?`<img src="${esc(photo)}" alt="" loading="lazy">`:esc((name.trim()[0]||'N').toUpperCase())}</span><div class="global-chat-content"><div><strong>${esc(name)}</strong><small>${new Date(row.created_at).toLocaleTimeString('sk-SK',{hour:'2-digit',minute:'2-digit'})}</small>${canModerate?`<button class="global-chat-delete" data-delete-message="${esc(row.id)}" aria-label="Vymazať správu od ${esc(name)}">${icon('trash')}<span>Vymazať</span></button>`:''}</div><p>${esc(row.body)}</p></div></article>`}).join('')||'<p class="muted">Buď prvý, kto niečo napíše.</p>';messages.scrollTop=messages.scrollHeight};
 const load=async()=>{const result=await client.from('global_chat_messages').select('id,user_id,body,created_at').order('created_at',{ascending:true}).limit(100);if(result.error)throw result.error;rows=result.data||[];const ids=[...new Set(rows.map(row=>row.user_id))];if(ids.length){const profiles=await client.from('profiles').select('id,display_name,username,avatar_path').in('id',ids);(profiles.data||[]).forEach(profile=>{profileNames.set(profile.id,profile.display_name||profile.username||'Nitra Space');const path=profile.avatar_path;if(path){const photo=client.storage.from('avatars').getPublicUrl(path).data.publicUrl;if(photo?.startsWith('https://'))profileAvatars.set(profile.id,photo)}})}paint()};
 try{await load()}catch(error){messages.innerHTML=`<p class="muted">Globálny chat ešte nie je pripravený. ${esc(error.message)}</p>`;return}
 form.onsubmit=async event=>{event.preventDefault();const input=form.elements.body,body=input.value.trim();if(!body)return;const button=form.querySelector('button');button.disabled=true;const result=await client.from('global_chat_messages').insert({user_id:user.id,body}).select('id,user_id,body,created_at').single();if(result.error)toast(result.error.message);else{rows.push(result.data);if(!profileNames.has(user.id)){const profile=await client.from('profiles').select('display_name,username,avatar_path').eq('id',user.id).maybeSingle();const p=profile.data;if(p){profileNames.set(user.id,p.display_name||p.username||'Ty');if(p.avatar_path){const photo=client.storage.from('avatars').getPublicUrl(p.avatar_path).data.publicUrl;if(photo?.startsWith('https://'))profileAvatars.set(user.id,photo)}}else profileNames.set(user.id,'Ty')}input.value='';paint()}button.disabled=false;input.focus()};
 channel=client.channel('global-chat').on('postgres_changes',{event:'INSERT',schema:'public',table:'global_chat_messages'},payload=>{if(!rows.some(row=>row.id===payload.new.id)){rows.push(payload.new);paint()}}).on('postgres_changes',{event:'DELETE',schema:'public',table:'global_chat_messages'},payload=>{rows=rows.filter(row=>row.id!==payload.old.id);paint()}).subscribe();
 const timer=setInterval(()=>{if(!document.hidden)load().catch(()=>{})},15000);onCleanup(()=>{clearInterval(timer);if(channel)client.removeChannel(channel)});
}
async function ensureSchoolRoomUser(){
 if(!roomClient)throw new Error('Supabase pripojenie nie je nastavené.')
 const existing=await roomClient.auth.getSession()
 if(existing.error)throw existing.error
 if(existing.data.session?.user)return existing.data.session.user
 const created=await roomClient.auth.signInAnonymously()
 if(created.error){
  if(created.error.code==='anonymous_provider_disabled')throw new Error('V Supabase zapni anonymné prihlásenie: Authentication → Sign In / Providers → Anonymous sign-ins.')
  throw created.error
 }
 return created.data.user
}
function schoolRoomErrorMessage(error){
 const message=String(error?.message||'')
 if(/V Supabase zapni anonymné prihlásenie/i.test(message))return message
 if(/Supabase pripojenie nie je nastavené/i.test(message))return 'Chýba pripojenie k Supabase. Roomky sú v náhľade viditeľné, chat sa pripojí po nastavení projektu.'
 if(error?.code==='PGRST205'||/school_chat_(rooms|messages)/i.test(message)||/schema cache|does not exist/i.test(message))return 'Supabase ešte nemá pripravené školské roomky. Treba spustiť priloženú migráciu.'
 if(error?.code==='anonymous_provider_disabled'||/anonymous sign-ins are disabled/i.test(message))return 'V Supabase zapni anonymné prihlásenie: Authentication → Sign In / Providers → Anonymous sign-ins.'
 if(/failed to fetch|network request failed/i.test(message))return 'Nepodarilo sa spojiť so Supabase. Skontroluj pripojenie a skús znova.'
 return 'Roomky sa zobrazujú, ale pripojenie k chatu zlyhalo. Skús znova.'
}
function updateSchoolRoomsStatus(){
 const status=document.querySelector('[data-school-rooms-status]')
 if(!status)return
 if(schoolRoomsError)status.innerHTML=`<span>${esc(schoolRoomsError)}</span> <button type="button" data-school-rooms-retry>Skúsiť znova</button>`
 else status.textContent=schoolRoomsLoading?'Pripájam chat…':''
}
function renderSchoolRoomCards(){
 const list=document.querySelector('[data-school-rooms-list]')
 if(!list)return
 list.innerHTML=schoolRooms.map(item=>`<button class="school-room-card" type="button" data-school-room="${esc(item.id)}"><span class="school-room-number">${String(item.id).padStart(2,'0')}</span><span class="school-room-card-copy"><strong>${esc(item.label)}</strong><small>Verejná · anonymná roomka</small></span>${icon('arrow')}</button>`).join('')
}
async function mountSchoolRooms(){
 if(route!=='rooms')return
 if(activeSchoolRoomId)return mountSchoolRoom(activeSchoolRoomId)
 if(!document.querySelector('[data-school-rooms-list]')||schoolRoomsAttempted)return
 schoolRoomsAttempted=true
 schoolRoomsLoading=true
 schoolRoomsError=''
 updateSchoolRoomsStatus()
 try{
  await ensureSchoolRoomUser()
  const result=await roomClient.from('school_chat_rooms').select('id,label').eq('is_active',true).order('id')
  if(result.error)throw result.error
  // Keep the curated, short room aliases in the UI even if an older database
  // still contains generic labels from an earlier preview.
  if(result.data?.length){const activeIds=new Set(result.data.map(item=>Number(item.id)));schoolRooms=defaultSchoolRooms.filter(item=>activeIds.has(item.id));renderSchoolRoomCards()}
  schoolRoomsError='';schoolRoomsLoaded=true
 }catch(error){schoolRoomsError=schoolRoomErrorMessage(error)}
 finally{schoolRoomsLoading=false;if(route==='rooms'&&!activeSchoolRoomId)updateSchoolRoomsStatus()}
}
async function mountSchoolRoom(roomId){
 const page=document.querySelector('[data-school-room-panel]'),messages=document.querySelector('[data-school-room-messages]'),form=document.querySelector('[data-school-room-form]')
 if(!page||!messages||!form||!roomClient)return
 if(schoolRoomChannel){roomClient.removeChannel(schoolRoomChannel);schoolRoomChannel=null}
 const current=++schoolRoomGeneration,id=Number(roomId)
 try{
  const user=await ensureSchoolRoomUser()
  if(current!==schoolRoomGeneration||!page.isConnected)return
  const result=await roomClient.from('school_chat_messages').select('id,room_id,author_id,author_name,body,created_at').eq('room_id',id).order('created_at',{ascending:false}).limit(100)
  if(result.error)throw result.error
  if(current!==schoolRoomGeneration||!page.isConnected)return
  let rows=(result.data||[]).reverse()
  const paint=()=>{if(!messages.isConnected)return;messages.innerHTML=rows.map(row=>`<article class="school-room-message ${row.author_id===user.id?'mine':''}"><div><strong>${esc(row.author_name||'Hosť')}</strong><time>${new Date(row.created_at).toLocaleTimeString('sk-SK',{hour:'2-digit',minute:'2-digit'})}</time></div><p>${esc(row.body)}</p></article>`).join('')||'<p class="school-room-empty">Zatiaľ tu nikto nenapísal. Začni konverzáciu.</p>';messages.scrollTop=messages.scrollHeight}
  paint()
  form.onsubmit=async event=>{event.preventDefault();const input=form.elements.body,body=input.value.trim();if(!body)return;const send=form.querySelector('button');send.disabled=true;try{const sent=await roomClient.from('school_chat_messages').insert({room_id:id,author_id:user.id,body}).select('id,room_id,author_id,author_name,body,created_at').single();if(sent.error)throw sent.error;if(!rows.some(row=>row.id===sent.data.id)){rows.push(sent.data);paint()}input.value='';input.focus()}catch(error){toast(error.message||'Správu sa nepodarilo odoslať.')}finally{send.disabled=false}}
  schoolRoomChannel=roomClient.channel(`school-room-${id}`,{config:{presence:{key:user.id}}}).on('presence',{event:'sync'},()=>{if(current===schoolRoomGeneration){const counter=document.querySelector('[data-school-room-online]');if(counter)counter.textContent=String(Object.keys(schoolRoomChannel.presenceState()).length||1)}}).on('postgres_changes',{event:'INSERT',schema:'public',table:'school_chat_messages',filter:`room_id=eq.${id}`},payload=>{if(current===schoolRoomGeneration&&!rows.some(row=>row.id===payload.new.id)){rows.push(payload.new);paint()}}).subscribe(async status=>{if(status==='SUBSCRIBED'&&current===schoolRoomGeneration){await schoolRoomChannel.track({joined_at:new Date().toISOString()});const state=document.querySelector('[data-school-room-state]');if(state)state.textContent='Pripojený'}else if((status==='CHANNEL_ERROR'||status==='TIMED_OUT')&&current===schoolRoomGeneration)toast('Realtime sa nepripojilo. Skús obnoviť roomku.')})
 }catch(error){if(current===schoolRoomGeneration&&messages.isConnected)messages.innerHTML=`<p class="school-room-error">${esc(schoolRoomErrorMessage(error))}</p>`}
}
function closeSchoolRoom(){if(schoolRoomChannel){roomClient?.removeChannel(schoolRoomChannel);schoolRoomChannel=null}schoolRoomGeneration++;activeSchoolRoomId=null;render()}
let roomPageGeneration=0
async function mountEventRoomPage(){
 const page=document.querySelector('[data-event-room-page]');if(!page||!client||!account())return
 const current=++roomPageGeneration,eventId=page.dataset.eventRoomPage,list=page.querySelector('[data-event-room-messages]'),status=page.querySelector('[data-event-room-status]'),form=page.querySelector('[data-event-room-form]')
 if(eventRoomChannel){client.removeChannel(eventRoomChannel);eventRoomChannel=null}
 try{
  const session=await client.auth.getSession(),user=session.data.session?.user;if(!user)throw new Error('Prihlás sa a potom otvor chat znova.')
  const [membership,admin]=await Promise.all([client.from('nitra_event_attendees').select('event_id').eq('event_id',eventId).eq('user_id',user.id).maybeSingle(),client.rpc('is_admin')])
  if(current!==roomPageGeneration||!page.isConnected)return
  if(!membership.data&&admin.data!==true){status.innerHTML=`<div class="event-room-gate"><p>Do chatu môžu vstúpiť prihlásení ľudia, ktorí sa pridali k tomuto eventu.</p><button class="primary" type="button" data-event-room-join="${esc(eventId)}">Idem na event · pridať sa do chatu ${icon('arrow')}</button></div>`;return}
  const result=await client.from('nitra_event_room_messages').select('id,event_id,user_id,author_name,body,created_at').eq('event_id',eventId).order('created_at',{ascending:true}).limit(100)
  if(result.error)throw result.error
  if(current!==roomPageGeneration||!page.isConnected)return
  let rows=result.data||[]
  const paint=()=>{if(!list?.isConnected)return;list.innerHTML=rows.map(row=>`<article class="event-room-message ${row.user_id===user.id?'mine':''}"><strong>${esc(row.author_name||'Nitra Space')}</strong><p>${esc(row.body)}</p><time>${new Date(row.created_at).toLocaleTimeString('sk-SK',{hour:'2-digit',minute:'2-digit'})}</time></article>`).join('')||'<p class="muted">Roomka je zatiaľ prázdna. Napíš prvú správu.</p>';list.scrollTop=list.scrollHeight}
  paint();status.remove();list.hidden=false;form.hidden=false
  form.onsubmit=async ev=>{ev.preventDefault();const input=form.elements.body,body=input.value.trim();if(!body)return;const send=form.querySelector('button');send.disabled=true;try{const sent=await client.from('nitra_event_room_messages').insert({event_id:eventId,user_id:user.id,body}).select('id,event_id,user_id,author_name,body,created_at').single();if(sent.error)throw sent.error;if(!rows.some(row=>row.id===sent.data.id)){rows.push(sent.data);paint()}input.value='';input.focus()}catch(error){toast(error.message||'Správu sa nepodarilo odoslať.')}finally{send.disabled=false}}
  eventRoomChannel=client.channel(`event-room-page-${eventId}`).on('postgres_changes',{event:'INSERT',schema:'public',table:'nitra_event_room_messages',filter:`event_id=eq.${eventId}`},payload=>{if(!rows.some(row=>row.id===payload.new.id)){rows.push(payload.new);paint()}}).subscribe()
 }catch(error){if(current===roomPageGeneration&&status)status.innerHTML=`<p class="muted">${esc(error.message||'Roomku sa nepodarilo načítať.')}</p>`}
}
async function joinEventPage(eventId){const session=await client.auth.getSession(),user=session.data.session?.user;if(!user){go('/account');toast('Prihlás sa, aby si sa pridal/a k eventu.');return}const {error}=await client.from('nitra_event_attendees').upsert({event_id:eventId,user_id:user.id},{onConflict:'event_id,user_id',ignoreDuplicates:true});if(error)throw error;render();toast('Si pridaný/á. Môžeš písať do chatu pred eventom.')}
async function load(){const id=++generation;const names=['chat','rooms'].includes(route)?[]:route==='event-room'?['events','account']:route==='events'?['events','account','isAdmin']:[route,'account'];await Promise.all([...new Set(names)].map(async n=>{const method={events:'loadEvents',polls:'loadPolls',people:'loadPeople',account:'loadAccount',isAdmin:'isAdmin'}[n];if(!method)return;const result=await api[method]();if(id!==generation)return;cache[n]=result;render()}))}
function navigate(){
 root.classList.remove('account-auth-open');cleanupFeature();generation++;
 if(schoolRoomChannel){roomClient?.removeChannel(schoolRoomChannel);schoolRoomChannel=null}schoolRoomGeneration++;activeSchoolRoomId=null
 const next=location.hash.slice(1).split('?')[0],path=location.pathname,isEventRoom=/^\/events\/[^/]+\/room\/?$/.test(path);
  const feature=/^\/(news|polls|people|account|messages|activity|admin|unreleased-tells)(\/|$)/.test(path)?path:
 ({news:'/news',people:'/people',account:'/account',polls:'/polls'}[next]||'');
 route=isEventRoom?'event-room':feature?feature.split('/')[1]:(routes[next]?next:'chat');filter='Všetky';
 if(sheet.open)sheet.close();shell();window.scrollTo(0,0);
 if(feature){
  document.querySelector('#main').innerHTML='<div class="editorial"><p id="feature-notice" role="status" aria-live="polite"></p><div id="feature-content"><p class="empty">Načítavam…</p></div></div>';
  mountFeature(client,feature,go);
 }else{if(!isEventRoom&&eventRoomChannel){client?.removeChannel(eventRoomChannel);eventRoomChannel=null}render();load()}
}
function go(url){history.pushState({},'',url);navigate()}
document.addEventListener('click',event=>{
 const a=event.target.closest('a[href]');if(!a||event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey||a.target||a.hasAttribute('download'))return;
 const url=new URL(a.href,location.href);
 if(url.origin!==location.origin||!(/^\/(news|polls|people|account|messages|activity|admin|unreleased-tells)(\/|$)/.test(url.pathname)||/^\/events\/[^/]+\/room\/?$/.test(url.pathname)||url.pathname==='/'&&url.hash))return;
 event.preventDefault();go(url.pathname+url.search+url.hash);
});
window.addEventListener('popstate',navigate);
window.addEventListener('nitra-auth-change',()=>{cache.account=null});
function modal(title,body){if(eventRoomChannel){client?.removeChannel(eventRoomChannel);eventRoomChannel=null}returnFocus=document.activeElement;sheet.innerHTML=`<button class="circle close" data-action="close" aria-label="Zavrieť">${icon('close')}</button><h2>${esc(title)}</h2>${body}`;if(!sheet.open)sheet.showModal()}
function needUser(){if(account())return true;location.hash='account';toast('Najprv sa prihlás do svojho účtu.');return false}
async function eventDetails(e){
 const session=client?await client.auth.getSession():null,user=session?.data?.session?.user||null
 let attending=false,isAdmin=false
 if(user){
  const [membership,admin]=await Promise.all([
   client.from('nitra_event_attendees').select('event_id').eq('event_id',e.id).eq('user_id',user.id).maybeSingle(),
   client.rpc('is_admin')
  ])
  if(membership.error)throw membership.error
  attending=Boolean(membership.data);isAdmin=admin.data===true
 }
 const canOpen=attending||isAdmin
 const group=/^https:\/\//i.test(e.instagramGroupUrl||'')?`<a class="primary event-instagram-link" href="${esc(e.instagramGroupUrl)}" target="_blank" rel="noopener noreferrer">Instagram skupina pre účastníkov ${icon('arrow')}</a>`:''
 modal(e.title,`${e.image?`<img class="detail-photo" src="${esc(e.image)}" alt="${esc(e.title)}">`:''}<p class="muted">${date(e.date)} · ${esc(e.place)}</p><p class="event-detail-copy">${esc(e.organizer||'')}<br>${esc(e.performer||'')}</p>${e.link?`<a class="outline event-source-link" href="${esc(e.link)}" target="_blank" rel="noopener noreferrer">Zdroj / vstupenky ${icon('arrow')}</a>`:''}${group?`<div class="event-social-actions">${group}</div>`:''}`)
}
async function openEventRoom(eventId){
 const event=data('events').find(item=>String(item.id)===String(eventId));if(!event)throw new Error('Event sa nenašiel.')
 if(event.roomEnabled===false)throw new Error('Organizátor vypol chat pre tento event.')
 const session=await client.auth.getSession(),user=session.data.session?.user
 if(!user){location.hash='account';toast('Prihlás sa, aby si sa pridal do chatu pred eventom.');return}
 const [membership,admin]=await Promise.all([
  client.from('nitra_event_attendees').select('event_id').eq('event_id',event.id).eq('user_id',user.id).maybeSingle(),
  client.rpc('is_admin')
 ])
 if(membership.error)throw membership.error
 if(!membership.data&&admin.data!==true)throw new Error('Najprv sa pridaj k eventu, až potom otvoríš chat.')
 modal(`Chat eventu · ${event.title}`,`<p class="muted event-room-subtitle">${date(event.date)} · ${esc(event.place)} · len pre ľudí, ktorí idú na event</p><div class="event-room-messages" data-event-room-messages aria-live="polite"><p class="muted">Načítavam správy…</p></div><form class="event-room-form" data-event-room-form><input name="body" maxlength="500" autocomplete="off" placeholder="Napíš do chatu pred eventom…" required><button class="primary" type="submit">Poslať ${icon('arrow')}</button></form>`)
 const list=sheet.querySelector('[data-event-room-messages]'),form=sheet.querySelector('[data-event-room-form]');let rows=[]
 const paint=()=>{if(!list?.isConnected)return;list.innerHTML=rows.map(row=>`<article class="event-room-message ${row.user_id===user.id?'mine':''}"><strong>${esc(row.author_name||'Nitra Space')}</strong><p>${esc(row.body)}</p><time>${new Date(row.created_at).toLocaleTimeString('sk-SK',{hour:'2-digit',minute:'2-digit'})}</time></article>`).join('')||'<p class="muted">Roomka je zatiaľ prázdna. Napíš prvú správu.</p>';list.scrollTop=list.scrollHeight}
 const result=await client.from('nitra_event_room_messages').select('id,event_id,user_id,author_name,body,created_at').eq('event_id',event.id).order('created_at',{ascending:true}).limit(100)
 if(result.error)throw result.error;rows=result.data||[];paint()
 form.onsubmit=async ev=>{ev.preventDefault();const input=form.elements.body,body=input.value.trim();if(!body)return;const submit=form.querySelector('button');submit.disabled=true;try{const sent=await client.from('nitra_event_room_messages').insert({event_id:event.id,user_id:user.id,body}).select('id,event_id,user_id,author_name,body,created_at').single();if(sent.error)throw sent.error;if(!rows.some(row=>row.id===sent.data.id)){rows.push(sent.data);paint()}input.value='';input.focus()}catch(error){toast(error.message||'Správu sa nepodarilo odoslať.')}finally{submit.disabled=false}}
 eventRoomChannel=client.channel(`event-room-${event.id}`).on('postgres_changes',{event:'INSERT',schema:'public',table:'nitra_event_room_messages',filter:`event_id=eq.${event.id}`},payload=>{if(!rows.some(row=>row.id===payload.new.id)){rows.push(payload.new);paint()}}).subscribe()
}
async function joinEventRoom(eventId){
 const session=await client.auth.getSession(),user=session.data.session?.user
 if(!user){location.hash='account';toast('Prihlás sa a potom sa pridaj k eventu.');return}
 const {error}=await client.from('nitra_event_attendees').upsert({event_id:eventId,user_id:user.id},{onConflict:'event_id,user_id',ignoreDuplicates:true})
 if(error)throw error
 const event=data('events').find(item=>String(item.id)===String(eventId));if(event)await openEventRoom(event.id)
 toast('Si pridaný/á do eventu.')
}
async function profile(username){modal('Načítavam profil…','');const result=await api.loadProfile(username);if(!sheet.open)return;if(result.status!=='ready'){sheet.innerHTML=`<button class="circle close" data-action="close" aria-label="Zavrieť">${icon('close')}</button><p class="empty">${esc(result.error||'Profil nie je dostupný.')}</p>`;return}const p=result.data;modal(p.name,`${(p.photos||[]).map(photo=>`<img class="detail-photo" src="${esc(photo.url)}" alt="Fotografia ${esc(p.name)}">`).join('')}<p class="muted">@${esc(p.username)}</p><p style="margin:16px 0;line-height:1.6">${esc(p.intro||p.bio||'Profil ešte nemá predstavenie.')}</p><div class="tags">${p.interests.map(t=>`<span>${esc(t)}</span>`).join('')}</div><button class="primary" data-match="${esc(p.id)}">Mám záujem${icon('heart')}</button>`)}
async function action(name){const p=account();if(name==='close'){sheet.close();return}if(name==='retry'){cache={};render();load();return}if(name==='auth-toggle'){register=!register;render();return}if(name==='auth-resend-code'){await api.resendAuthCode();toast('Nový kód sme poslali na e-mail.');return}if(name==='search'){modal('Nájdi svoj space.','<label>Hľadať sekcie, eventy a ľudí<input id="search" type="search" placeholder="Meno, event, ankety…" autocomplete="off"></label><div id="search-results"></div>');return}if(name==='signout'){await api.signOut();cache={};navigate();return}if(!needUser())return;if(name==='security'){modal('Bezpečnosť.','<p class="muted">Zmenu hesla a vymazanie účtu nájdeš v existujúcich zabezpečených nastaveniach.</p>'+button('/account','Otvoriť nastavenia'));return}if(name==='edit'||name==='privacy')modal(name==='edit'?'Tvoj profil.':'Súkromie.',`<form data-form="profile">${name==='edit'?`<label>Meno<input name="name" required maxlength="80" value="${esc(p.name)}"></label><label>Používateľské meno<input name="username" pattern="[a-z0-9_]{3,24}" required value="${esc(p.username)}"></label><label>O mne<textarea name="bio" maxlength="500">${esc(p.bio)}</textarea></label><label>Záujmy oddelené čiarkou<input name="interests" value="${esc(p.interests.join(', '))}"></label>`:`<label><input type="checkbox" name="discoverable" ${p.discoverable?'checked':''}>Zobrazovať môj profil ľuďom</label>`}<p class="form-message" role="alert"></p><button class="primary">Uložiť zmeny${icon('arrow')}</button></form>`)}
document.addEventListener('click',ev=>{const room=ev.target.closest('[data-school-room]');if(room){activeSchoolRoomId=room.dataset.schoolRoom;render();return}if(ev.target.closest('[data-school-room-next]')){const index=schoolRooms.findIndex(item=>String(item.id)===String(activeSchoolRoomId));activeSchoolRoomId=schoolRooms[(index+1)%schoolRooms.length]?.id??null;render();return}if(ev.target.closest('[data-school-rooms-back]')){closeSchoolRoom();return}if(ev.target.closest('[data-school-rooms-retry]')){schoolRoomsLoaded=false;schoolRoomsAttempted=false;schoolRoomsLoading=false;schoolRoomsError='';updateSchoolRoomsStatus();void mountSchoolRooms()}})
document.addEventListener('click',async ev=>{const button=ev.target.closest('[data-delete-message]');if(!button)return;ev.preventDefault();if(!confirm('Naozaj chceš vymazať túto správu?'))return;button.disabled=true;try{const result=await client.from('global_chat_messages').delete().eq('id',button.dataset.deleteMessage).select('id').maybeSingle();if(result.error)throw result.error;if(!result.data)throw new Error('Nemáš oprávnenie vymazať túto správu. Ak si admin, najprv treba aktivovať databázové pravidlo.');const row=button.closest('.global-chat-message');row?.remove();const list=document.querySelector('[data-global-messages]');if(list&&!list.querySelector('.global-chat-message'))list.innerHTML='<p class="muted">Buď prvý, kto niečo napíše.</p>';toast('Správa vymazaná.')}catch(error){toast(error.message||'Správu sa nepodarilo vymazať.')}finally{if(button.isConnected)button.disabled=false}})
document.addEventListener('click',async ev=>{const el=ev.target.closest('button,[data-profile]');if(!el)return;try{if(el.dataset.action)await action(el.dataset.action);if(el.dataset.filter){filter=el.dataset.filter;render()}if(el.dataset.event){const e=data('events').find(x=>String(x.id)===el.dataset.event);if(e)await eventDetails(e)}if(el.dataset.eventJoin)await joinEventRoom(el.dataset.eventJoin);if(el.dataset.eventRoom)await openEventRoom(el.dataset.eventRoom);if(el.dataset.eventRoomJoin)await joinEventPage(el.dataset.eventRoomJoin);if(el.dataset.profile)await profile(el.dataset.profile);if(el.dataset.poll&&needUser()){el.disabled=true;await api.vote(el.dataset.poll,el.dataset.option);cache.polls=await api.loadPolls();if(route==='polls')render();toast('Hlas je uložený. Ďakujeme.')}if(el.dataset.match&&needUser()){el.disabled=true;const r=await api.requestMatch(el.dataset.match);toast(r.status==='connected'?'Máte spojenie! Nájdeš ho v aktivite účtu.':'Záujem bol odoslaný.')}}catch(e){toast(e.message||'Akciu sa nepodarilo dokončiť.')}finally{if(el.isConnected)el.disabled=false}})
document.addEventListener('submit',async ev=>{const form=ev.target;if(!form.dataset.form)return;ev.preventDefault();const submit=form.querySelector('[type=submit],.primary'),message=form.querySelector('.form-message');submit.disabled=true;message.textContent='';try{const fields=Object.fromEntries(new FormData(form));if(form.dataset.form==='auth'){const r=await api[register?'signUp':'signIn'](fields);if(r.confirmationRequired){showAuthCode(form,r.email||fields.email);return}cache.account=await api.loadAccount();render();toast('Si prihlásený.')}else if(form.dataset.form==='auth-code'){await api.verifyAuthCode(fields.code);register=false;cache.account=await api.loadAccount();go('/chat');toast('E-mail potvrdený. Si prihlásený a môžeš používať Nitra Space.')}else{if(form.elements.interests)fields.interests=fields.interests.split(',');if(form.elements.discoverable)fields.discoverable=form.elements.discoverable.checked;await api.updateProfile(fields);cache.account=await api.loadAccount();sheet.close();render();toast('Profil je uložený.')}}catch(e){message.textContent=e.message||'Niečo sa nepodarilo.'}finally{if(submit.isConnected)submit.disabled=false}})
document.addEventListener('input',ev=>{if(ev.target.id!=='search')return;const q=ev.target.value.toLocaleLowerCase('sk').trim();const items=[...Object.entries(routes).map(([id,label])=>({label,href:id==='chat'?'/chat':['polls','account','unreleased-tells'].includes(id)?'/'+id:'/space#'+id})),...data('events').map(e=>({label:e.title,href:'/space#events'})),...data('people').map(p=>({label:p.name,href:'/space#people'}))];document.querySelector('#search-results').innerHTML=items.filter(x=>x.label.toLocaleLowerCase('sk').includes(q)).slice(0,10).map(x=>`<a class="search-result" href="${x.href}">${esc(x.label)}</a>`).join('')||'<p class="muted">Nič sa nenašlo.</p>'})
sheet.addEventListener('close',()=>{if(eventRoomChannel){client?.removeChannel(eventRoomChannel);eventRoomChannel=null}returnFocus?.isConnected&&returnFocus.focus()});sheet.addEventListener('click',e=>{if(e.target.closest('a[href^="#"]'))sheet.close()})
window.addEventListener('hashchange',navigate);document.addEventListener('visibilitychange',()=>{document.documentElement.dataset.paused=String(document.hidden)})
